"""L15 drafts from visual inspection of all23 pages; not independent review."""
from authoring_helpers import DraftBatch,formula
b=DraftBatch('W03-L15',3,'L15','Joint and Cartesian manipulator dynamics',450,'robotics-integration-author-L15')
dyn=formula('τ=M(q)qddot+V(q,qdot)+G(q)',{'τ':'joint effort vector','M':'joint inertia matrix','q,qdot,qddot':'joint positions, rates and accelerations','V':'velocity-dependent joint effort','G':'gravity joint effort'},{'τ,V,G':'N·m for revolute coordinates; N for prismatic coordinates','M':'joint-coordinate-dependent inertia units','q,qdot,qddot':'joint-type-specific position/rate/acceleration units'},['Ideal rigid links; friction and extra loads omitted unless explicitly added.'])
cart=formula('Mx=J⁻ᵀMJ⁻¹; Vx=J⁻ᵀ(V−MJ⁻¹Jdot qdot); Gx=J⁻ᵀG',{'J':'square nonsingular Jacobian mapping qdot to the chosen task-velocity components','Mx':'task-space inertia','Vx':'task-space velocity term','Gx':'task-space gravity term','M,V,G':'joint-space dynamics terms','Jdot':'time derivative of the same Jacobian components'},{'Mx':'inertia units appropriate to task coordinates','Vx,Gx':'force or power-conjugate generalized task-effort units','J':'task velocity per joint velocity'},['Use one consistent frame and a power-conjugate task velocity/effort pair; in moving axes, distinguish derivative of components from inertial acceleration.'])
model='Two planar revolute joints; massless links with point masses m1 at the first link tip and m2 at the second link tip; θ1 measured from horizontal and θ2 relative.'
b.add(453,'joint-dynamics-roles','Terms of joint dynamics','In τ=M(q)qddot+V(q,qdot)+G(q), which association is correct?', ['M: inertia; V: velocity-dependent effort; G: gravity effort','M: gravity; V: inertia; G: velocity-dependent effort','M: velocity-dependent effort; V: gravity; G: inertia','M: a position Jacobian; V: angular position; G: joint acceleration'],0,'The matrix multiplies joint acceleration; V groups centrifugal/Coriolis terms and G represents gravity.', ['This matches each term’s physical role.','This exchanges all three roles.','This exchanges all three roles.','The equation is a force/torque balance, not a position mapping.'],typ='match',difficulty='easy',formulas=[dyn])
b.add(453,'joint-dimensions','Dimensions of joint dynamics','For n independent joint coordinates, what are the dimensions of M, qddot and V?', ['n×n, n×1 and n×1','n×1, n×n and n×1','n×n, 1×n and n×n','6×n, n×1 and 6×1 for every robot'],0,'The n×n inertia matrix maps n joint accelerations to n joint efforts, so V must also have n entries.', ['The matrix-vector product and sum have n entries.','The proposed product does not give the required joint vector.','A row acceleration and matrix V do not match the displayed sum.','The joint-space equation is sized by joint count, not always six.'],typ='definition',difficulty='easy',formulas=[dyn])
b.add([453,469],'first-order-state','First-order state representation','For an n-joint second-order dynamics model, which state gives the usual first-order representation?', ['x=[q;qdot], with 2n components','x=q only, with n components, without any extra velocity information','x=qddot only, with n components','x=[M;G], with no joint positions or velocities'],0,'Position and velocity together determine the instantaneous state; acceleration is obtained from the dynamics and input.', ['Both variables needed by the second-order system are included.','The future motion also depends on current velocity.','Acceleration alone does not specify current position or velocity.','Model coefficients do not replace the configuration and rate state.'],typ='derivation',difficulty='easy',formulas=[dyn])
b.add([453,455],'inertia-dependence','Configuration dependence is not universal entrywise','The slide says each mass-matrix entry depends on all joint positions, but its 2R example has M22=m2 l2²; what follows?', ['M can depend on configuration overall while particular entries are constant or depend on fewer coordinates','The constant M22 makes the entire mass matrix invalid','Every entry must be multiplied by θ1θ2 to restore correctness','M cannot be symmetric if one entry is constant'],0,'The example directly shows that configuration dependence is a property of the matrix function, not a requirement that every entry vary with every coordinate.', ['This preserves the equation and qualifies the overbroad prose.','Constant inertia entries can be physically correct.','Adding arbitrary coordinate factors changes the dynamics.','Symmetry constrains corresponding off-diagonal entries, not whether entries vary.'],typ='source-reconciliation',conflict='Physical page453 says each element depends on all joint positions; page455 displays a constant M22 and no θ1 dependence.')
b.add(454,'point-mass-model','Reading the two-link mass model','Where are the point masses located in the two-link example?', ['m1 at the elbow and m2 at the end of link2','Both at the base joint','m1 and m2 at the centers of uniform massive links','Both at the end of link2'],0,'The diagram places m1 at the first link’s distal end and m2 at the second link’s distal end.', ['This matches the marked circles and the point-mass model.','The masses are drawn away from the base.','Center-of-link masses would give different inertia coefficients.','The first mass is at the elbow, not the tool tip.'],typ='diagram',difficulty='easy',assumptions=[model])
b.add([454,455],'inertia-numerical','Evaluate the point-mass inertia','For the displayed 2R model, let m1=2 kg, m2=3 kg, l1=1 m, l2=2 m and θ2=90°; what is M in kg·m²?', ['[[17,12],[12,12]]','[[29,18],[18,12]]','[[17,0],[0,12]]','[[5,3],[3,3]]'],0,'cosθ2=0, so M11=3·4+(2+3)·1=17 and M12=M21=M22=3·4=12.', ['All four entries follow the displayed coefficients.','This retains the cosθ2=1 coupling terms.','The off-diagonal m2l2² term survives at90°.','This treats l2 as1 rather than2.'],typ='numerical',assumptions=[model],steps=['Set cos90°=0.','Compute m2l2²=12 and (m1+m2)l1²=5.','Assemble M=[[17,12],[12,12]].'],formulas=[formula('M11=m2l2²+2m2l1l2cosθ2+(m1+m2)l1²; M12=M21=m2l2²+m2l1l2cosθ2; M22=m2l2²',{'m1,m2':'point masses','l1,l2':'link lengths','θ2':'relative joint angle','Mij':'inertia entries'},{'m1,m2':'kg','l1,l2':'m','θ2':'rad','Mij':'kg·m²'},[model])])
b.add(455,'inertia-positive-definite','Positive-definite inertia and energy','For a nondegenerate independent-coordinate rigid-body model, which statement expresses positive-definite M?', ['zᵀMz>0 for every nonzero joint-rate vector z','Every off-diagonal M entry must be positive','det M=0 whenever the tool Jacobian is singular','M must equal the identity matrix'],0,'The kinetic energy ½zᵀMz is positive for nonzero generalized velocity under these assumptions; this implies invertibility, not an identity matrix.', ['This is the relevant quadratic-form condition.','Positive definiteness does not require every off-diagonal entry to be positive.','Kinematic Jacobian singularity and inertial degeneracy are distinct.','Positive-definite matrices need not be identity.'],typ='derivation',assumptions=['Independent coordinates and a model with positive kinetic energy for every nonzero generalized velocity.'],formulas=[formula('T=½qdotᵀM(q)qdot',{'T':'kinetic energy','qdot':'joint-rate vector','M':'joint inertia matrix'},{'T':'J','qdot':'joint-type-specific rate units','M':'compatible inertia units'})])
b.add([455,463],'inertia-versus-jacobian','Inertia need not fail at kinematic singularity','For positive m1,m2,l1,l2, det M=l1²l2²m2(m1+m2 sin²θ2); what happens at θ2=0?', ['M remains invertible although the displayed 2×2 task Jacobian is singular','M and the task Jacobian both necessarily become zero matrices','M becomes singular because sinθ2=0 appears in det J','The point mass m1 disappears from det M'],0,'At θ2=0, det M=l1²l2²m1m2>0, while det J=l1l2sinθ2=0.', ['The two determinants describe different mappings.','Neither matrix must be the zero matrix.','A zero Jacobian determinant does not force the inertia determinant to vanish.','The positive m1 term is what remains in the determinant.'],typ='derivation',assumptions=[model,'All masses and lengths are positive.'],formulas=[formula('det M=l1²l2²m2(m1+m2sin²θ2); det J=l1l2sinθ2',{'M':'joint inertia','J':'displayed translational task Jacobian','m1,m2':'point masses','l1,l2':'link lengths','θ2':'relative angle'},{'det M':'kg²·m⁴','det J':'m²','m1,m2':'kg','l1,l2':'m','θ2':'rad'})])
b.add(456,'velocity-products','Squared and mixed rates','In the slide’s separated velocity terms, which pair is labeled centrifugal and Coriolis, respectively?', ['A coefficient times qdot_i²; a coefficient times qdot_i qdot_j with i≠j','A coefficient times qddot_i; a coefficient times q_i','A gravity term; a joint acceleration term','A mixed-rate product; a squared-rate term'],0,'The slide labels the squared-rate terms centrifugal and the mixed-rate terms Coriolis in this coordinate expansion.', ['This matches the lecture’s decomposition.','Acceleration and position are not the displayed velocity products.','These belong to other dynamics terms.','This reverses the displayed labels.'],typ='match',difficulty='easy')
b.add([454,456],'velocity-numerical','Evaluate the joint velocity term','Using m2=3 kg, l1=1 m, l2=2 m, θ2=90°, qdot1=1 rad/s and qdot2=2 rad/s, what is V?', ['(-48,6) N·m','(-24,6) N·m','(-48,-6) N·m','(-36,6) N·m'],0,'With h=m2l1l2sinθ2=6, V1=−h(qdot2²+2qdot1qdot2)=−6(4+4)=−48 and V2=h qdot1²=6.', ['Both square and twice-product terms are included.','This omits the mixed-rate term.','The second component has a positive sign in this model.','This uses only one copy of the mixed-rate product.'],typ='numerical',steps=['Compute h=3·1·2·1=6.','Compute V1=−6(2²+2·1·2)=−48.','Compute V2=6·1²=6.'],assumptions=[model],formulas=[formula('V=[−h(qdot2²+2qdot1qdot2), h qdot1²]ᵀ; h=m2l1l2sinθ2',{'V':'velocity-dependent torque','h':'configuration coefficient','qdot1,qdot2':'joint rates','m2':'distal point mass','l1,l2':'lengths','θ2':'relative angle'},{'V':'N·m','h':'kg·m²','qdot1,qdot2':'rad/s','m2':'kg','l1,l2':'m','θ2':'rad'})])
b.add(456,'gravity-dependence','Gravity at rest','What does qdot=0 and qddot=0 imply for the ideal joint equation at a fixed configuration?', ['τ=G(q), which need not be zero','τ=0 because both motion derivatives vanish','τ=M(q)q, because position replaces acceleration','τ=V(q,0), while G is removed'],0,'The inertia and velocity terms vanish at rest, leaving the torque needed to balance gravity.', ['The remaining gravity load can be nonzero.','Static equilibrium may require actuator torque.','Position cannot be substituted for acceleration.','Gravity remains even when velocity is zero.'],typ='derivation',difficulty='easy',formulas=[dyn])
b.add([454,456],'gravity-numerical','Evaluate gravity torques','For m1=2 kg, m2=3 kg, l1=1 m, l2=2 m, θ1=0, θ2=90° and g=10 m/s², what is G?', ['(50,0) N·m','(0,0) N·m','(110,60) N·m','(30,0) N·m'],0,'cos(θ1+θ2)=0 removes the distal-link moment term; (m1+m2)l1gcosθ1=50 remains in G1.', ['This includes both masses supported through link1.','The horizontal first link still has a gravity moment.','This uses cos(θ1+θ2)=1 instead of0.','The proximal point mass also contributes.'],typ='numerical',assumptions=[model],steps=['Evaluate cosθ1=1 and cos(θ1+θ2)=0.','Compute G1=0+5·1·10=50.','Compute G2=3·2·10·0=0.'],formulas=[formula('G1=m2l2g cos(θ1+θ2)+(m1+m2)l1gcosθ1; G2=m2l2gcos(θ1+θ2)',{'G1,G2':'gravity torques','m1,m2':'point masses','l1,l2':'lengths','g':'gravitational acceleration magnitude','θ1,θ2':'joint angles'},{'G1,G2':'N·m','m1,m2':'kg','l1,l2':'m','g':'m/s²','θ1,θ2':'rad'},[model])])
b.add(457,'coefficient-dimensions','Dimensions of separated velocity coefficients','For n=4, what are the dimensions of B and C in B[qdot qdot]+C[qdot²]?', ['B is4×6 and C is4×4','B is4×3 and C is4×4','B is6×4 and C is4×4','B and C are both4×16'],0,'There are4·3/2=6 distinct unordered mixed-rate products and four squared rates.', ['These dimensions map both product vectors to four efforts.','Three adjacent pairs omit other mixed pairs.','The B matrix must output four efforts.','The expansion does not use all ordered pairs as independent terms.'],typ='numerical',difficulty='easy',steps=['Count unordered pairs:4 choose2=6.','B has one row per joint and one column per pair.','C has one column per squared joint rate.'])
b.add([457,466],'mixed-pair-shorthand','Complete mixed-rate vector','For three joints, which vector contains all unordered distinct mixed-rate products required by the stated n(n−1)/2 count?', ['[qdot1qdot2, qdot1qdot3, qdot2qdot3]ᵀ','[qdot1qdot2, qdot2qdot3]ᵀ','[qdot1², qdot2², qdot3²]ᵀ','[qdot1qdot2, qdot2qdot1, qdot2qdot3]ᵀ'],0,'Three joints have three unordered pairs:12,13 and23; adjacent pairs alone are incomplete and reversed duplicates are not new pairs.', ['Every distinct unordered pair is included once.','The nonadjacent pair13 is missing.','These are squared rates handled by C.','The12 pair is duplicated while13 is omitted.'],typ='source-reconciliation',conflict='Pages457 and466 show adjacent-pair shorthand while claiming a vector of length n(n−1)/2; the general expansion needs every unordered pair.')
b.add(458,'two-link-coefficients','Two-link separated matrices','With h=m2l1l2sinθ2, which B and C recover V=[−h(qdot2²+2qdot1qdot2),h qdot1²]ᵀ?', ['B=[−2h,0]ᵀ and C=[[0,−h],[h,0]]','B=[−h,0]ᵀ and C=[[0,−h],[h,0]]','B=[−2h,0]ᵀ and C=[[0,h],[−h,0]]','B=[0,−2h]ᵀ and C=[[−h,0],[0,h]]'],0,'Multiplying B by qdot1qdot2 gives the mixed first component; multiplying C by[qdot1²,qdot2²]ᵀ gives the two squared terms.', ['The products reconstruct both components.','The mixed contribution loses its factor2.','The squared terms have reversed signs.','The coefficients act on the wrong components and rates.'],typ='derivation',assumptions=['Here C multiplies squared rates; it is not the commonly used velocity-dependent C(q,qdot) multiplying qdot.'])
b.add([457,458],'c-notation','Two meanings of C','Why must the slide’s C(q)[qdot²] not be blindly substituted for C(q,qdot)qdot in another text?', ['The matrices multiply different rate vectors and therefore have different definitions','The letter C always means the same numerical matrix in robotics','The slide’s C must be the gravity vector','Both matrices must be zero whenever qdot is nonzero'],0,'The local notation defines a configuration-only matrix of squared-rate coefficients; another convention uses a velocity-dependent matrix multiplying first-power rates.', ['The product and definition determine the meaning.','A reused symbol does not guarantee identical objects.','Gravity is separately denoted G.','Velocity-dependent effects can be nonzero during motion.'],typ='conceptual',difficulty='easy')
b.save()
print(len(b.questions),'initial L15 drafts saved.')
b.add(459,'cartesian-roles','Task-space effort and acceleration','In the Cartesian dynamics equation, what must the task effort F be paired with?', ['The task velocity whose power is Fᵀ times that velocity','Any orientation-parameter derivative, regardless of the effort definition','Joint acceleration, so that Fᵀqddot is mechanical power','Joint position, so that Fᵀq is mechanical power'],0,'The generalized force or wrench must be power-conjugate to the selected task velocity; a geometric angular velocity and an arbitrary orientation-parameter derivative are not interchangeable.', ['This keeps the coordinate and effort definitions consistent.','Orientation coordinates can require an additional mapping and conjugate effort.','Force times acceleration is not mechanical power.','Force times position is not a power rate.'],typ='conceptual',assumptions=['Use a consistent definition of Cartesian/task velocity and its conjugate effort.'])
b.add(460,'transpose-power','Why torque uses the transpose','If v=Jqdot and joint power equals task power, which effort relation follows?', ['τ=JᵀF','τ=JF','τ=J⁻¹F for every rectangular J','τ=FᵀJ as a column vector without transposing'],0,'Fᵀv=FᵀJqdot=(JᵀF)ᵀqdot, so matching coefficients of qdot gives τ=JᵀF.', ['This follows directly from equality of power.','The transpose is needed to map task effort into joint effort.','A rectangular matrix need not have an ordinary inverse, and inversion is not the power derivation.','FᵀJ is a row; the joint-effort column is its transpose.'],typ='derivation',steps=['Substitute v=Jqdot into Fᵀv.','Rewrite FᵀJqdot as (JᵀF)ᵀqdot.','Compare with τᵀqdot.'],formulas=[formula('v=Jqdot; τ=JᵀF; τᵀqdot=Fᵀv',{'v':'task velocity','J':'matching Jacobian','qdot':'joint velocity','F':'conjugate task effort','τ':'joint effort'},{'τᵀqdot,Fᵀv':'W','v,qdot':'coordinate-specific velocity units','F,τ':'compatible effort units'},['Matching frames and power-conjugate variables.'])])
b.add(460,'inverse-validity','When the inverse-transpose step exists','What extra condition is needed for the slide’s F=J⁻ᵀτ step, beyond τ=JᵀF?', ['J is square and nonsingular','J is merely differentiable','J has more columns than rows, with no further condition','J contains only positive entries'],0,'An ordinary inverse transpose exists only for a square nonsingular matrix; the transpose mapping itself does not require that condition.', ['This is the required inverse condition.','Differentiability does not imply invertibility.','A nonsquare matrix has no ordinary two-sided inverse.','Entry signs do not establish an inverse.'],typ='conceptual',difficulty='easy',assumptions=['Ordinary matrix inverse, not a separately defined pseudoinverse or redundant-robot formulation.'])
b.add(460,'frame-consistency','A common frame is required','A force is given in tool coordinates but J is in base coordinates; what is required before using τ=JᵀF?', ['Transform one representation so J and F use compatible frames and conventions','Multiply them directly because torque is frame-invariant','Transpose F but leave the frame mismatch unchanged','Discard the moment part of F to remove the mismatch'],0,'The matrix-vector components must describe compatible coordinate bases and, for a full wrench, compatible reference points.', ['This preserves physical meaning and power.','A coordinate-invariant physical result still requires compatible component representations.','Transposition does not change the coordinate frame.','Dropping moment components changes the load rather than fixing its representation.'],typ='scenario',difficulty='easy')
b.add(461,'jacobian-derivative','Product rule for task acceleration','For task coordinates in fixed axes with xdot=J(q)qdot, which acceleration equation is correct?', ['xddot=Jqddot+Jdot qdot','xddot=Jqddot only for every motion','xddot=Jdot qddot+Jqdot','xddot=Jqddot−Jdot qdot'],0,'Differentiate both factors of J(q)qdot; J changes with configuration, producing Jdot qdot.', ['Both product-rule terms are included.','The omitted term need not vanish.','This interchanges the derivatives of the factors.','The product rule adds the second term.'],typ='derivation',difficulty='easy',assumptions=['Fixed-axis task coordinates and a differentiable Jacobian.'])
b.add(461,'jacobian-acceleration-numeric','Solve for joint acceleration','Let J=diag(2,1), Jdot qdot=(1,−2) m/s² and desired xddot=(5,4) m/s²; what is qddot?', ['(2,6) rad/s²','(3,2) rad/s²','(2.5,4) rad/s²','(8,6) rad/s²'],0,'Subtract the velocity term to get(4,6), then apply J⁻¹=diag(1/2,1), yielding(2,6).', ['This subtracts before applying the inverse.','This adds the Jdot contribution instead of subtracting it.','This omits the Jdot contribution.','This multiplies the first component by2 rather than dividing.'],typ='numerical',steps=['Compute xddot−Jdot qdot=(4,6).','Apply diag(1/2,1).','Obtain(2,6) rad/s².'],formulas=[formula('qddot=J⁻¹(xddot−Jdot qdot)',{'qddot':'joint angular acceleration','J':'translational Jacobian','xddot':'task acceleration','Jdot qdot':'velocity-dependent task acceleration'},{'qddot':'rad/s²','J':'m/rad','xddot,Jdot qdot':'m/s²'},['Square nonsingular J and fixed task-coordinate axes.'])])
b.add(462,'cartesian-inertia','Transformed inertia order','Which expression is the slide’s task-space inertia for a square nonsingular J?', ['Mx=J⁻ᵀMJ⁻¹','Mx=JMJᵀ','Mx=J⁻¹MJ⁻ᵀ','Mx=MJ⁻¹J⁻ᵀ without changing the order'],0,'Substitute qddot=J⁻¹(xddot−Jdot qdot) into F=J⁻ᵀτ; the xddot coefficient is J⁻ᵀMJ⁻¹.', ['This is the coefficient in the substituted equation.','This uses J instead of its inverse.','The left and right factors are reversed.','Matrices cannot generally be reordered.'],typ='derivation',formulas=[cart])
b.add(462,'cartesian-velocity','Transformed velocity term','Which correction appears in Vx in addition to J⁻ᵀV?', ['−J⁻ᵀMJ⁻¹Jdot qdot','+J⁻ᵀMJ⁻¹Jdot qdot','−J⁻ᵀM qdot with no Jdot','No correction is ever required'],0,'Solving the acceleration mapping subtracts J⁻¹Jdot qdot before multiplication by M and J⁻ᵀ.', ['This is the product-rule correction with the correct sign and order.','The sign is opposite to the acceleration substitution.','This drops the derivative and changes the physical units.','The Jacobian generally changes during motion.'],typ='derivation',formulas=[cart])
b.add(462,'cartesian-spd','Positive inertia under coordinate change','If M is symmetric positive definite and J is invertible, why is Mx=J⁻ᵀMJ⁻¹ positive definite?', ['For nonzero y, yᵀMx y=(J⁻¹y)ᵀM(J⁻¹y)>0','Because every entry of J⁻¹ must be positive','Because Mx necessarily equals M','Because J⁻ᵀMJ⁻¹ is a similarity transform with exactly the same eigenvalues'],0,'The congruence transformation preserves the positive quadratic form; J⁻¹y is nonzero for nonzero y.', ['This proves positivity directly.','Inverse-matrix entries can have either sign.','Different task coordinates generally change the matrix.','This is a congruence, not generally an eigenvalue-preserving similarity.'],typ='derivation',formulas=[cart],assumptions=['M symmetric positive definite; square nonsingular J.'])
b.add([462,464],'cartesian-singularity','Directional apparent inertia near singularity','For Mx=diag(m2+m1/sin²θ2,m2) with m1>0, what happens as θ2 approaches0 away from the singular point?', ['The first diagonal term diverges while the second stays m2','Both diagonal terms approach0','Both diagonal terms necessarily diverge at the same rate','The joint inertia determinant must also approach0'],0,'Only the first entry contains1/sin²θ2; the second is constant, illustrating direction-dependent task-space ill-conditioning.', ['This follows from the displayed diagonal form.','The reciprocal squared sine grows rather than vanishes.','The second entry has no singular denominator.','Joint inertia can stay positive definite at a kinematic singularity.'],typ='derivation',assumptions=['Positive point masses and lengths; use the expression only at nonsingular configurations.'])
b.add(463,'tool-jacobian','Identify the displayed Jacobian basis','The 2R example gives J=[[l1 sinθ2,0],[l1 cosθ2+l2,l2]]; what distinguishes it from the usual base-frame translational Jacobian?', ['It expresses endpoint velocity in axes aligned with link2, so θ1 dependence cancels','It is the base-frame Jacobian and must contain no θ1 for any planar robot','It maps Cartesian force to joint velocity','It is a rotation matrix because it is2×2'],0,'Rotating the base-frame translational velocity into link2-aligned axes gives the displayed matrix; its columns retain length dimensions.', ['This explains both the frame choice and the absent θ1.','The standard fixed-base Jacobian contains θ1 and θ1+θ2 terms.','Its displayed role is velocity mapping, not force-to-velocity conversion.','A square Jacobian need not be orthogonal or dimensionless.'],typ='derivation',assumptions=[model,'The task velocity is expressed in axes rotated by θ1+θ2 from the base.'])
b.add(463,'tool-jacobian-inverse','Evaluate the displayed inverse','For l1=1 m, l2=2 m and θ2=90°, J=[[1,0],[2,2]]; what is J⁻¹?', ['[[1,0],[−1,1/2]]','[[1,0],[1,1/2]]','[[1,−1],[0,1/2]]','[[1,0],[−2,2]]'],0,'The lower-triangular inverse has first row(1,0); solving2qdot1+2qdot2=v2 gives the second row(−1,1/2).', ['Multiplication by J gives the identity.','The lower-left sign must cancel the coupling.','This incorrectly transposes the coupling location.','The second row is not normalized by the diagonal2.'],typ='numerical',steps=['Invert the first equation v1=qdot1.','Solve qdot2=v2/2−v1.','Read off the two inverse rows.'],assumptions=[model],formulas=[formula('J⁻¹=[ [l2,0], [−l1cosθ2−l2,l1sinθ2] ]/(l1l2sinθ2)',{'J':'displayed tool-axis translational Jacobian','l1,l2':'lengths','θ2':'relative angle'},{'J':'m/rad','J⁻¹':'rad/m','l1,l2':'m','θ2':'rad'},['sinθ2 is nonzero.'])])
b.add(463,'tool-jacobian-time','Differentiate the displayed Jacobian','At l1=1 m, θ2=90° and qdot2=2 rad/s, what is Jdot for J=[[l1sinθ2,0],[l1cosθ2+l2,l2]]?', ['[[0,0],[−2,0]]','[[2,0],[0,0]]','[[0,0],[2,0]]','[[0,0],[0,0]]'],0,'The derivatives of the first column are l1cosθ2 qdot2=0 and −l1sinθ2 qdot2=−2; the second column is constant.', ['This applies the chain rule to both varying entries.','This treats sin90° as its derivative.','The derivative of cosine has a negative sign.','A zero cosine does not make both derivatives zero.'],typ='numerical',steps=['Differentiate sinθ2 and cosθ2 with respect to time.','Substitute sin90°=1, cos90°=0 and qdot2=2.','Keep the constant second column zero.'],assumptions=['Derivative of the displayed moving-axis matrix components.'])
b.add([461,463],'moving-frame-derivative','Component derivative is not inertial acceleration','Let v_T be endpoint velocity components in rotating tool axes; how does their derivative relate to inertial acceleration expressed in those axes?', ['a_T=dv_T/dt+ω_T×v_T','a_T=dv_T/dt for every rotating frame','a_T=dv_T/dt−ω_T×v_T','a_T=ω_T×v_T with no component derivative'],0,'The transport theorem adds the basis-rotation term; the slide’s derivative of J_T qdot is a derivative of components unless that term is separately included.', ['This includes both the component change and basis rotation.','A rotating basis adds a transport term.','The inertial derivative has the positive transport term under this convention.','The components themselves may also change.'],typ='source-reconciliation',assumptions=['v_T is an ordinary vector’s components in axes rotating at ω_T relative to the inertial frame.'],formulas=[formula('a_T=dot(v_T)+ω_T×v_T',{'a_T':'inertial derivative of velocity expressed in T','dot(v_T)':'ordinary time derivative of velocity components in T','ω_T':'angular velocity of frame T relative to inertial axes, expressed in T','v_T':'velocity components in T'},{'a_T,dot(v_T)':'m/s²','ω_T':'rad/s','v_T':'m/s'})],conflict='Pages461–463 differentiate task-velocity components while allowing a tool frame; the notation χddot must not be silently identified with inertial acceleration components in rotating axes.')
b.add(464,'cartesian-mass-numeric','Numerical task inertia','For m1=2 kg, m2=3 kg and θ2=30°, what is the displayed task inertia Mx?', ['diag(11,3) kg','diag(7,3) kg','diag(5,3) kg','diag(3,11) kg'],0,'sin²30°=1/4, so m2+m1/sin²θ2=3+2/(1/4)=11 and the second entry remains3.', ['This uses the squared sine in the denominator.','This divides by sin30° instead of its square.','This uses sin²θ2=1.','The two task-axis entries have been exchanged.'],typ='numerical',steps=['Compute sin30°=1/2 and square it to1/4.','Compute3+2/(1/4)=11.','Keep the second diagonal entry3.'],formulas=[formula('Mx=diag(m2+m1/sin²θ2,m2)',{'Mx':'tool-axis translational task inertia','m1,m2':'point masses','θ2':'relative joint angle'},{'Mx,m1,m2':'kg','θ2':'rad'},[model,'sinθ2≠0.'])])
b.add(465,'cartesian-velocity-numeric','Evaluate transformed velocity force','For m1=2, m2=3 kg, l1=1, l2=2 m, θ2=90°, qdot1=1 and qdot2=2 rad/s, the slide gives Mx=diag(5,3); what is its expanded Vx?', ['(−54,9) N','(−48,6) N','(−24,3) N','(54,−9) N'],0,'At cosθ2=0 and sinθ2=1, Vx1=−6·1²−6·2²−12·1·2=−54 and Vx2=3·1²+3·1·2=9.', ['This evaluates the displayed transformed expression.','These are the joint-space V components, not task forces.','This is J⁻ᵀV without the Jacobian-derivative correction.','Both signs have been reversed.'],typ='numerical',steps=['Set sine to1 and cosine to0.','Compute the first component−6−24−24=−54.','Compute the second component3+6=9.'],formulas=[cart],assumptions=[model,'Use the slide’s derivative of tool-velocity components, not inertial acceleration components.'])
b.add(465,'cartesian-gravity-numeric','Evaluate transformed gravity force','For m1=2, m2=3 kg, g=10 m/s², θ1=0 and θ2=90°, what is Gx=[m1gcosθ1/sinθ2+m2gsin(θ1+θ2),m2gcos(θ1+θ2)]ᵀ?', ['(50,0) N','(20,0) N','(0,50) N','(50,30) N'],0,'The first component is20+30=50 and cos90° makes the second component zero.', ['Both first-component contributions are present.','This omits the distal mass contribution.','The task-axis components have been exchanged.','The second component incorrectly uses cos90°=1.'],typ='numerical',steps=['Evaluate cos0=1, sin90°=1 and cos90°=0.','Compute2·10+3·10=50.','Compute3·10·0=0.'],formulas=[cart],assumptions=[model])
b.add(466,'gravity-back-transform','Gravity force versus joint gravity torque','Which identity resolves the slide’s prose saying Gx is the same as joint-space gravity?', ['JᵀGx=G; Gx itself is generally not equal to G','Gx=G numerically for every J','J⁻¹Gx=G for every J','Gx must be zero whenever G is nonzero'],0,'Because Gx=J⁻ᵀG, transforming it back gives JᵀGx=G; the force-space vector and joint-effort vector are different objects.', ['This matches the two displayed equations and their units.','Different coordinates and effort units generally change the vector.','The effort back-transformation uses Jᵀ.','The invertible map does not turn a nonzero vector into zero.'],typ='source-reconciliation',formulas=[cart],conflict='Page466 prose names Gx as the same as joint-space gravity, while its joint-torque equation correctly uses G and prior pages define Gx=J⁻ᵀG.')
b.add(466,'cartesian-torque-velocity','Why the velocity coefficients change','Why can Bx and Cx in the Cartesian-acceleration torque equation differ from the original joint-space B and C?', ['Replacing qddot introduces a Jdot qdot correction that combines with the old velocity terms','Changing coordinates removes every velocity-dependent term','The gravity term is multiplied by joint velocity','The point masses automatically become configuration-dependent masses'],0,'The substitution qddot=J⁻¹(xddot−Jdot qdot) moves a velocity-dependent contribution into the grouped quadratic terms.', ['This explains the new coefficients without changing the physical model.','The product-rule correction generally remains.','Gravity does not acquire a velocity factor from this substitution.','The same masses are expressed through a different dynamics mapping.'],typ='derivation',formulas=[cart])
b.save();print(len(b.questions),'L15 drafts saved through Cartesian dynamics.')
friction=formula('τ_comp=c sgn(qdot)+v qdot; τ_resist=−τ_comp',{'τ_comp':'actuator effort needed to compensate sliding friction','τ_resist':'actual resisting joint torque','c':'Coulomb coefficient','v':'viscous coefficient','qdot':'joint angular velocity'},{'τ_comp,τ_resist,c':'N·m','v':'N·m·s/rad','qdot':'rad/s'},['Positive c,v and nonzero sliding velocity; static friction needs a separate treatment.'])
b.add(467,'friction-figure-qualification','Qualify the quoted friction percentage','How should the slide’s “friction is responsible for25% of required torque in typical situations” statement be used?', ['As the slide’s stated illustrative figure, not a universal value for every robot and motion','As an exact constant valid at every speed and configuration','As proof that friction can always be omitted without consequence','As a measured value for this specific robot without any further data'],0,'The page supplies the25% statement without a dataset or operating conditions; the bank can preserve the attribution but cannot establish a universal measured fraction.', ['This distinguishes source reporting from independent validation.','The share depends on the mechanism and operating conditions.','A potentially substantial term is not a reason to omit it.','The page supplies no measurement record for a specific robot.'],typ='source-reconciliation',difficulty='easy',conflict='Physical page467 states25% in typical situations without supporting measurement conditions or a dataset.')
b.add(467,'friction-model-types','Viscous and Coulomb friction','Which comparison matches the simple sliding-friction models?', ['Viscous magnitude scales with speed; Coulomb magnitude is constant and its sign follows motion direction','Viscous magnitude is constant; Coulomb magnitude scales linearly with speed','Both magnitudes depend only on joint position','Both torques keep the same sign when velocity reverses'],0,'The viscous term is v qdot and the Coulomb term is c sgn(qdot), under the compensating-effort convention.', ['This follows from the two formulas.','This exchanges the models.','The displayed simple models depend on velocity, not position.','Both displayed terms reverse sign when nonzero velocity reverses.'],typ='match',difficulty='easy',formulas=[friction])
b.add([467,468],'friction-sign','Compensation and resisting torque have opposite signs','With c=2 N·m, v=0.5 N·m·s/rad and qdot=−4 rad/s, what are compensating torque and actual resisting torque?', ['−4 N·m and +4 N·m','+4 N·m and −4 N·m','−2 N·m and +2 N·m','0 N·m and0 N·m'],0,'Compensation is2·(−1)+0.5·(−4)=−4; actual friction opposes the negative motion and is therefore+4.', ['The actuator compensation and physical resistance are opposites.','This swaps compensation with actual resistance.','This omits the viscous contribution.','Both model terms are nonzero at the stated speed.'],typ='numerical',steps=['Use sgn(−4)=−1.','Compute compensation−2−2=−4 N·m.','Negate it to obtain actual resistance+4 N·m.'],formulas=[friction])
b.add([467,468],'friction-power','Dissipation in the combined friction model','For c,v≥0 and nonzero qdot, which expression is the power removed by actual friction, with a positive sign for dissipated power?', ['c|qdot|+v qdot²','c qdot+v qdot² with no absolute value','−c|qdot|−v qdot²','c+v regardless of speed'],0,'Actual friction power is−c|qdot|−v qdot²; its negative is the nonnegative dissipated power.', ['Both terms are nonnegative for the stated coefficients.','The Coulomb contribution cannot become negative solely because motion reverses.','This is power delivered by the resisting torque, not the positive dissipation amount.','Power depends on velocity as well as torque coefficients.'],typ='derivation',formulas=[friction])
b.add(467,'friction-at-zero','What the simple sign law misses at rest','If a numerical implementation sets sgn(0)=0, what cannot be inferred from c sgn(qdot) alone?', ['That real static friction must be zero at rest','That the model contribution evaluates to zero at qdot=0','That the sliding Coulomb magnitude is c at nonzero speed','That the sign changes between positive and negative nonzero speed'],0,'A single-valued sign-at-zero rule does not model the range of static friction that can balance a load before sliding.', ['The simple sliding law does not establish real static-friction behavior.','That is exactly what this chosen numerical convention returns.','For nonzero velocity the sign magnitude is1.','The sign function changes across zero.'],typ='conceptual',assumptions=['The question distinguishes the implementation convention from a physical static-friction model.'])
b.add(468,'friction-symbol','The reused symbol F','Why must F in τ=Mqddot+V+G+F(q,qdot) be distinguished from F in the earlier Cartesian equation?', ['Here F denotes joint friction effort; earlier it denotes task-space force/torque','They must be the same vector because the letter is the same','Here F is joint acceleration; earlier it is friction','The added F is dimensionless in both equations'],0,'The local definition changes the meaning and coordinate space of F, so its units and role must be read from the equation.', ['This follows the source’s local notation.','A reused symbol can denote different quantities.','The added term is an effort, not acceleration.','Every term in the joint sum must have joint-effort units.'],typ='conceptual',difficulty='easy')
b.add(468,'rigid-model-limits','What rigid links omit','Which effect is explicitly omitted when the links are treated as perfectly rigid?', ['Bending modes that can produce structural resonances','All gravitational forces','Every Coriolis term','All dependence on joint configuration'],0,'Rigid-link dynamics excludes deformation; flexible bending can add resonant behavior beyond that model.', ['This is the stated model limitation.','Gravity is already included in G.','Velocity coupling is already included in V.','The inertia and gravity terms can depend on configuration.'],typ='definition',difficulty='easy')
b.add(469,'forward-dynamics','Forward versus inverse dynamics','What does the simulation step compute from current q,qdot and applied τ?', ['qddot by solving Mqddot=τ−V−G−F','τ from a prescribed qddot only','q directly without velocity or initial conditions','The Jacobian inverse instead of the inertia solve'],0,'Forward dynamics determines acceleration from applied effort and the current state; integrating then advances velocity and position.', ['This is the rearranged dynamics equation.','That is the inverse-dynamics direction.','A second-order trajectory requires state and integration.','The acceleration solve uses the inertia matrix.'],typ='definition',difficulty='easy',formulas=[dyn])
b.add(469,'forward-solve-numeric','A coupled forward-dynamics solve','Let M=[[2,1],[1,2]] kg·m², τ=(8,7), V=(1,0), G=(2,3) and F=(1,0), all efforts in N·m; what is qddot?', ['(4/3,4/3) rad/s²','(2,2) rad/s²','(4,4) rad/s²','(8/3,−4/3) rad/s²'],0,'The net right side is(4,4); M⁻¹=(1/3)[[2,−1],[−1,2]], yielding(4/3,4/3).', ['This solves the coupled matrix equation.','This divides by diagonal entries while ignoring coupling.','This leaves the net effort unchanged as though M=I.','This introduces an incorrect sign/coupling result.'],typ='numerical',steps=['Subtract V,G,F from τ to obtain(4,4).','Use det M=3 and M⁻¹=(1/3)[[2,−1],[−1,2]].','Multiply to get(4/3,4/3) rad/s².'],formulas=[formula('qddot=M⁻¹(τ−V−G−F)',{'qddot':'joint acceleration','M':'joint inertia','τ':'applied torque','V,G,F':'velocity, gravity and friction torques'},{'qddot':'rad/s²','M':'kg·m²','τ,V,G,F':'N·m'},['M invertible; stated2R numerical example.'])])
b.add(469,'first-order-equations','Complete first-order dynamics','With x=[q;v] and v=qdot, which state derivative matches the friction-inclusive equation?', ['xdot=[v; M(q)⁻¹(τ−V(q,v)−G(q)−F(q,v))]','xdot=[q; M(q)τ]','xdot=[v; M(q)⁻¹(τ+V+G+F)]','xdot=[qddot;v]'],0,'The position derivative is velocity, and the velocity derivative is the forward-dynamics acceleration.', ['This gives both derivative blocks in the correct order.','The first block is not the position derivative and the second omits loads/inversion.','The known load terms must be subtracted.','The derivative blocks have been assigned to the wrong state components.'],typ='derivation',formulas=[dyn])
b.add(469,'simulation-initial-state','Initial state is not universally at rest','The slide gives q(0)=q0 and qdot(0)=0 as initial conditions; what is the correct interpretation?', ['Zero initial velocity is the example choice, not a requirement of forward dynamics','Every dynamically valid robot trajectory must start from rest','The specified position is unnecessary because only acceleration matters','The initial state must contain torque but not velocity'],0,'A simulation needs initial position and velocity; zero velocity is one permitted choice.', ['This distinguishes an example from a universal condition.','Nonzero initial velocity is valid if specified consistently.','Initial position affects the state-dependent dynamics and trajectory.','Applied input does not replace initial velocity.'],typ='conceptual',difficulty='easy')
b.add(469,'integration-naming','Distinguish the displayed position update','The slide labels q_new=q+qdot Δt+½qddot Δt² “Euler integration”; how does it differ from plain forward Euler applied to [q;qdot]?', ['It retains a constant-acceleration second-order position term that plain forward Euler omits','It removes the velocity contribution entirely','It is the exact solution for every state-dependent acceleration and time step','It updates position using only the new velocity, as symplectic Euler does'],0,'Plain forward Euler gives q_new=q+qdot Δt; the displayed formula adds the Taylor/constant-acceleration term, while still updating velocity with its first derivative.', ['This states the exact difference without claiming universal exactness.','The qdot Δt term is still present.','Acceleration may change over the step.','Using qdot_new would give a full qddot Δt² term, not one half.'],typ='source-reconciliation',conflict='Page469 labels a velocity Euler step plus a second-order constant-acceleration position step collectively as Euler integration.')
b.add(469,'integration-step-numeric','Use the displayed constant-acceleration step','With q=1 rad, qdot=2 rad/s, qddot=−4 rad/s² and Δt=0.1 s, what do the displayed updates give?', ['q_new=1.18 rad and qdot_new=1.6 rad/s','q_new=1.20 rad and qdot_new=1.6 rad/s','q_new=1.16 rad and qdot_new=1.6 rad/s','q_new=1.22 rad and qdot_new=2.4 rad/s'],0,'The velocity becomes2−0.4=1.6; position becomes1+0.2−0.02=1.18.', ['This uses the printed half-acceleration position term.','This is the plain forward-Euler position update, omitting that term.','This uses the new velocity for the full step instead of the displayed formula.','Both acceleration contributions have the wrong sign.'],typ='numerical',steps=['Compute Δt²=0.01 s².','Update velocity:2+(−4)·0.1=1.6.','Update position:1+2·0.1+0.5·(−4)·0.01=1.18.'],assumptions=['Use the exact displayed formulas with acceleration treated as constant over this step.'],formulas=[formula('qdot_new=qdot+qddot Δt; q_new=q+qdot Δt+½qddot Δt²',{'q,q_new':'old/new position','qdot,qdot_new':'old/new velocity','qddot':'acceleration held for the step','Δt':'step duration'},{'q,q_new':'rad','qdot,qdot_new':'rad/s','qddot':'rad/s²','Δt':'s'},['Constant-acceleration position approximation, not plain forward Euler for the entire state.'])])
b.add(469,'simulation-feedback','Reevaluate the model during simulation','Why should M,V,G and friction normally be evaluated again as the simulated state changes?', ['Their arguments can change with q and qdot, changing the computed acceleration','They must remain frozen at the initial values for every nonlinear model','Only the number of links changes during a time step','Reevaluation automatically makes any integration step exact'],0,'The dynamics is state-dependent; retaining the initial coefficients without justification replaces it with a different approximation.', ['This preserves the nonlinear state dependence.','Freezing coefficients is an additional approximation, not a universal rule.','The robot structure does not normally change merely because time advances.','Numerical integration error can remain after reevaluation.'],typ='scenario',difficulty='easy',formulas=[dyn])
b.save();print(len(b.questions),'L15 drafts;',len(b.concepts),'concept records.')
